function Write_Integrated_Report(folder)
% Write a report section using only the current measured CSV files.
root=fileparts(fileparts(mfilename('fullpath')));
metrics=readtable(fullfile(folder,'metrics.csv'),'TextType','string');
storage=readtable(fullfile(folder,'storage_quality.csv'),'TextType','string');
q=readtable(fullfile(root,'Results','Khaled','quantization_summary.csv'),'TextType','string');
pairs=readtable(fullfile(folder,'integration_comparison.csv'),'TextType','string');
sine=readtable(fullfile(folder,'sine_quantization_check.csv'));
[~,runName]=fileparts(folder);
relative=['../Results/Integrated/' runName '/'];
path=fullfile(root,'Reports','Quantization_and_Evaluation.md');
fid=fopen(path,'w'); assert(fid>=0,'Cannot write the report section.');
closer=onCleanup(@()fclose(fid));
fprintf(fid,'# Tasks 3 and 4: Quantization, storage and quality evaluation\n\n');
fprintf(fid,'Measured run: `%s`. MATLAB %s. Insert Task 3 after the existing sampling section, then Task 4. The full table can be placed in a results appendix.\n\n',runName,version('-release'));
fprintf(fid,['This implementation completes the quantization stage at Jesher''s request and connects it to Abdulrahman''s actual MATLAB and Simulink sampling outputs. ' ...
    'Jesher''s evaluator measures those combined outputs. The earlier independent demo remains a separate experiment. ' ...
    'The task labels identify team responsibilities; they do not claim independent authorship or approval by another student.\n\n']);
fprintf(fid,'## 3.1 Uniform requantization\n\n');
fprintf(fid,['The mono original has 882,005 samples at 44,100 Hz and 16-bit PCM resolution. Sampling precedes quantization. ' ...
    'At the native rate the quantizer receives the original samples. At lower rates it receives the exact double-valued sampling arrays, rather than the rounded WAV copies. ' ...
    'The MATLAB quantizer receives MATLAB sampling outputs; the Simulink quantizer receives outputs from the four actual sampling models. No independent amplitude normalization is applied.\n\n']);
fprintf(fid,['For B = 8, 4 or 2, the step is delta = 2/2^B. The algorithm rounds x/delta to the nearest integer, with exact half ties away from zero, ' ...
    'limits the index to [-2^(B-1), 2^(B-1)-1], then multiplies by delta. There are 2^B available levels between -1 and 1-delta. ' ...
    'For 2 bits the levels are -1, -0.5, 0 and 0.5. The 16-bit setting bypasses requantization and preserves the sampling-stage doubles as a control. ' ...
    'No dither is added. Samples that would round beyond the largest signed index are saturated and counted.\n\n']);
fprintf(fid,'## 3.2 Isolated quantization error\n\n');
fprintf(fid,['Quantization error is e_q[n] = samplingInput[n] - quantizedOutput[n]. Both arrays have the same rate and time origin. ' ...
    'This isolates quantization from the total sampling/reconstruction error. The error histogram uses the full recording. ' ...
    'The approximation delta^2/12 assumes unsaturated, approximately uniform rounding error; speech/music and coarse quantization need not satisfy it. ' ...
    'Positive-end saturation can also exceed a half-step error.\n\n']);
fprintf(fid,'**Table 3.1. Native-rate quantization of the actual recording, MATLAB.** No rate change or reconstruction filter is involved.\n\n');
fprintf(fid,'| Effective bits | Observed levels | Saturated samples | Error MSE | Mean error | Maximum absolute error | SNR (dB) |\n| --- | --- | --- | --- | --- | --- | --- |\n');
for bits=[8 4 2]
    row=q(q.Fs==44100 & q.platform=="matlab" & q.effectiveBits==bits,:);
    fprintf(fid,'| %d | %d | %d | %.8g | %.8g | %.8g | %.4f |\n',bits,row.distinctOutputLevels,row.saturatedSamples,row.errorMSE,row.errorMean,row.maxAbsError,row.quantizationOnlySNRdB);
end
fprintf(fid,'\nObserved levels can be fewer than the available levels because the recording does not visit every amplitude.\n\n');
fprintf(fid,['At 8 bits, the measured error MSE is close to delta^2/12. The low-bit histogram is concentrated near zero rather than uniform, ' ...
    'and its time variation follows the changing content of the recording. At 2 bits, many small input amplitudes map to zero. ' ...
    'Saturation and the signal-dependent error distribution explain why an exact 6 dB improvement per added bit is not expected for every condition.\n\n']);
for bits=[8 4 2]
    id=sprintf('speechmusic_fs44100_b%02d_native_matlab',bits);
    figureLink(fid,relative,[id '_quantization.png'],sprintf('Figure 3.%d. Native-rate %d-bit quantization error versus time and full-record error distribution. The error is original minus quantized samples, before WAV export.',find([8 4 2]==bits),bits));
end
fprintf(fid,'## 3.3 Storage and effective precision\n\n');
fprintf(fid,['The ideal packed payload is N times B bits for one channel, or ceil(N times B / 8) whole bytes. This is a theoretical packing calculation, not an implemented low-bit file format. ' ...
    'Every exported WAV is mono PCM16, so its actual sample payload is 2N bytes irrespective of effective quantizer bits. The table records measured file size and header overhead. ' ...
    'Reducing the sampling rate reduces the WAV sample count; reducing effective precision alone does not shrink this PCM16 carrier.\n\n']);
fprintf(fid,'**Table 3.2. Native-rate precision/storage comparison, MATLAB.** SNR is measured after WAV re-import.\n\n');
fprintf(fid,'| Bits | Ideal packed payload (bytes) | Actual WAV (bytes) | WAV container bits | SNR (dB) |\n| --- | --- | --- | --- | --- |\n');
for bits=[16 8 4 2]
    row=storage(storage.Fs==44100 & storage.platform=="matlab" & storage.effectiveBits==bits,:);
    fprintf(fid,'| %d | %d | %d | %d | %.4f |\n',bits,row.idealPackedPayloadBytes,row.wavFileBytes,row.wavContainerBits,row.exportedSnrDb);
end
figureLink(fid,relative,'native_quality_storage.png','Figure 3.4. Native-rate measured SNR and theoretical packed payload versus actual PCM16 WAV storage. The 16-bit zero-error control is excluded from the finite-SNR plot.');
baseline=storage(storage.Fs==44100 & storage.effectiveBits==16 & storage.platform=="matlab",:);
example=storage(storage.caseId=="speechmusic_fs22050_b08_lpf_matlab",:);
low=storage(storage.caseId=="speechmusic_fs4000_b02_lpf_matlab",:);
fprintf(fid,['For a combined example, the filtered 22,050 Hz, 8-bit case uses %d actual WAV bytes, compared with %d for the native control, ' ...
    'and has exported SNR %.4f dB. The filtered 4,000 Hz, 2-bit case uses %d bytes but its SNR falls to %.4f dB. ' ...
    'These examples quantify the rate/quality tradeoff in the actual exported files; further reducing effective bits at a fixed rate saves theoretical packed payload only. ' ...
    'The [full storage-quality table](%sstorage_quality.csv) includes every case and both metric representations.\n\n'], ...
    example.wavFileBytes,baseline.wavFileBytes,example.exportedSnrDb,low.wavFileBytes,low.exportedSnrDb,relative);
fprintf(fid,'## 3.4 Theory and platform implementation\n\n');
fprintf(fid,['The familiar full-scale sine approximation is SNR approximately 6.02B + 1.76 dB. For a sine with peak 0.5, its amplitude correction is 20 log10(0.5). ' ...
    'It assumes high-resolution, unsaturated quantization and an appropriate error distribution. A separate 997 Hz, two-second sine checks the trend without sampling-rate reduction.\n\n']);
fprintf(fid,'| Bits | Measured sine SNR (dB) | High-resolution prediction (dB) |\n| --- | --- | --- |\n');
for k=1:height(sine), fprintf(fid,'| %d | %.4f | %.4f |\n',sine.bits(k),sine.measuredSNRdB(k),sine.highResolutionPrediction(k)); end
fprintf(fid,['\nThe approximation becomes less reliable at very low precision. It is not a prediction of the combined sampling-plus-quantization SNR. ' ...
    'The Simulink design implements divide, round, saturate and multiply using visible arithmetic blocks, with a control bypass and error output. ' ...
    'One vector frame contains the entire recording; simulation stop time zero processes that frame once and does not mean zero-duration audio.\n\n']);
figureLink(fid,relative,'quantization_model.png','Figure 3.5. Actual Simulink quantization model. The input is the sampling-stage array; quantized samples and isolated quantization error are logged for evaluation.');
fprintf(fid,'## 4.1 Total quality measurement and alignment\n\n');
fprintf(fid,['For total degradation, the processed array is reconstructed at 44,100 Hz with resample(samples,p,q,10,5) using the inverse conversion ratio. ' ...
    'The first 882,005 reconstructed samples are compared with the original times from 0 through 882004/44100 seconds. Known sampling-filter delay is already compensated. ' ...
    'No extra time shift, gain normalization or error-selected edge trimming is applied. Reconstruction restores the time grid, not removed bandwidth or aliased information.\n\n']);
fprintf(fid,['NMSE = sum((x - xhat).^2) / sum(x.^2). SNR in dB = 10 log10(sum(x.^2) / sum((x - xhat).^2)). ' ...
    'The same positive-error comparison satisfies SNR = -10 log10(NMSE). The unchanged control has NMSE zero and infinite SNR. ' ...
    'A silent reference with zero error has undefined normalized metrics, reported as NaN. ' ...
    'The nmse/snrDb columns score processing arrays; exportedNmse/exportedSnrDb score the WAV after export, re-import and reconstruction.\n\n']);
fprintf(fid,'## 4.2 Results across all conditions\n\n');
fprintf(fid,['There are four native-rate precision settings and four lower rates with two filter modes and four precision settings: 36 conditions per platform, 72 actual results. ' ...
    'The following complete table reports exported-WAV results. The machine-readable metrics table also retains processing-array scores and timing/export metadata.\n\n']);
fprintf(fid,'**Table 4.1. Complete combined results after PCM16 WAV re-import and reconstruction.**\n\n');
fprintf(fid,'| Rate (Hz) | Bits | Filter | MATLAB NMSE | MATLAB SNR (dB) | Simulink NMSE | Simulink SNR (dB) |\n| --- | --- | --- | --- | --- | --- | --- |\n');
a=sortrows(metrics(metrics.platform=="matlab",:),{'Fs','filterMode','effectiveBits'},{'descend','ascend','descend'});
for k=1:height(a)
    b=metrics(metrics.caseId==replace(a.caseId(k),'_matlab','_simulink'),:);
    fprintf(fid,'| %d | %d | %s | %.8g | %.4f | %.8g | %.4f |\n',a.Fs(k),a.effectiveBits(k),a.filterMode(k),a.exportedNmse(k),a.exportedSnrDb(k),b.exportedNmse,b.exportedSnrDb);
end
fprintf(fid,'\nFilter `none` at 8/4 kHz means linear interpolation without a dedicated anti-aliasing LPF. At 22.05/11.025 kHz it means direct sample selection. `lpf` uses Abdulrahman''s documented filtered conversion.\n\n');
fprintf(fid,'## 4.3 Representative waveform, FFT and spectrogram comparisons\n\n');
fprintf(fid,['Each figure compares the original at left with the exported WAV reconstructed to the original grid at right. Rows show waveform, normalized full-record single-sided FFT and PSD spectrogram. ' ...
    'FFT scaling retains DC and accounts for odd/even sample counts. Spectrograms use a periodic 1,024-sample Hann window, 768-sample overlap and 2,048-point FFT. ' ...
    'The frequency axis is in kHz; PSD remains per Hz. Display floors are -160 dB. Quantization errors are plotted separately at the processed rate.\n\n']);
ids={'speechmusic_fs44100_b04_native_matlab','speechmusic_fs22050_b08_lpf_matlab','speechmusic_fs4000_b02_none_matlab'};
for k=1:numel(ids)
    row=metrics(metrics.caseId==string(ids{k}),:);
    caption=sprintf('Figure 4.%d. %d Hz, %d effective bits, %s path. Exported-WAV NMSE %.8g and SNR %.4f dB.',k,row.Fs,row.effectiveBits,row.filterMode,row.exportedNmse,row.exportedSnrDb);
    figureLink(fid,relative,[ids{k} '_comparison.png'],caption);
end
fprintf(fid,['Coarse quantization removes many small-amplitude variations and can flatten quiet regions to zero. Lower-rate conversion removes or folds higher-frequency information depending on the filter path. ' ...
    'A narrow reconstructed spectrum alone does not prove that aliasing was avoided before rate conversion; interpret it with the sampling method and the known-tone checks in Task 2.\n\n']);
fprintf(fid,'## 4.4 MATLAB and Simulink agreement\n\n');
fprintf(fid,['Identical-input quantizer checks passed exactly for all actual Simulink cases and explicit boundary fixtures. ' ...
    'The largest actual sampling-stage difference across the 36 platform pairs was %.12g. ' ...
    'The combined outputs contain %d pairs with quantizer decision-boundary differences, involving %d samples in total across those pairs. ' ...
    'Each such difference is exactly one quantizer step and is verified to originate from input roundoff at a half-step threshold. ' ...
    'The complete resolved comparison is integration_comparison.csv. The original evaluator''s stricter generic comparison is retained for transparency.\n\n'], ...
    max(pairs.samplingMaxAbsDifference),nnz(pairs.explainedBoundarySamples>0),sum(pairs.explainedBoundarySamples));
fprintf(fid,['The integration checks also verify all 72 unique identities, timing/rates, unchanged controls, quantizer level limits, isolated errors, WAV sample counts and PCM representations. ' ...
    'The evaluator verifies the ZIP members byte for byte against its manifest. Numerical checks do not constitute human listening or peer sign-off.\n\n']);
fprintf(fid,'## 4.5 Playback and remaining human observations\n\n');
fprintf(fid,['RUN_DEMO exports a selected case. PLAY_PROJECT_AUDIO plays the original followed by that WAV at their actual rates, without independent level normalization. ' ...
    'The new full matrix has no recorded human listening observations yet. The supplied listening_template.csv links every case to its exported NMSE/SNR and leaves listener, device/volume and observations blank. ' ...
    'Earlier observations that three sampling-control clips sounded clear do not establish the audibility of these new reduced-bit outputs. ' ...
    'Students still need to listen, record actual observations, rehearse the explanation and complete final report/package approval.\n\n']);
fprintf(fid,'## 4.6 Code and report placement\n\n');
fprintf(fid,['Use RUN_PROJECT for the full run and PROJECT_SETTINGS plus RUN_DEMO for the live case. See [QUICK_START](../QUICK_START.md) for the simple file map. ' ...
    'Use Figures 3.1-3.5 and 4.1-4.3 in the corresponding sections as space permits. Table 4.1 can be moved to Appendix B with a cross-reference in Section 4.2. ' ...
    'Additional comparison images and the complete storage CSV are supporting results; a separate code appendix is optional. ' ...
    'The shared Word report has not been edited by this generated section. Preserve the earlier sampling content and add these sections after it.\n']);
fprintf('Report section written: %s\n',path);
end
function figureLink(fid,relative,name,caption)
fprintf(fid,'\n![%s](%sfigures/%s)\n\n%s\n\n',caption,relative,name,caption);
end
